from pathlib import Path
import json

data=Path.home()/".local/share/prediction-chat-bridge"
cid="CONT-e91d594cb6c782b9e7b2668d"
cp=data/"continuations"/f"{cid}.json"

def load(p):
    try:return json.loads(p.read_text(encoding="utf-8"))
    except Exception:return None

if cp.is_file():
    c=load(cp) or {}
    print("HEARTBEAT_LIVE=A_EXISTS state="+str(c.get("state"))+" recovery="+str(c.get("recovery_reason")),flush=True)
    raise SystemExit(41)

recoveries=[]
root=data/"continuations"
if root.is_dir():
    for p in root.glob("CONT-*.json"):
        o=load(p)
        if isinstance(o,dict) and o.get("recovery_reason")=="RESULT_ACK_TIMEOUT":
            recoveries.append((float(o.get("created_at") or 0),str(o.get("source_task_id") or "")))
recoveries.sort(reverse=True)

if recoveries:
    print("HEARTBEAT_LIVE=OTHER_RECOVERY count="+str(len(recoveries))+" newest="+recoveries[0][1],flush=True)
    raise SystemExit(42)

print("HEARTBEAT_LIVE=NO_RECOVERY_RECORDS",flush=True)
raise SystemExit(43)
